#' DML: Binary Treatment (Interactive Model)
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param target .
#' @param lrn_g .
#' @param lrn_m .
#' @param trim .
#' @param plot .
#' @param rule .
#' @param folds .
#' @param reps .
#' @param seed .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nuis} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reps} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$psPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
dmlirm <- function(
    data,
    outcome,
    treat,
    covs,
    target = "ate",
    lrn_g = "lasso",
    lrn_m = "lasso",
    trim = 0.01,
    plot = TRUE,
    rule = "lambda.min",
    folds = 5,
    reps = 1,
    seed = 1234,
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dmlirm requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- dmlirmOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        target = target,
        lrn_g = lrn_g,
        lrn_m = lrn_m,
        trim = trim,
        plot = plot,
        rule = rule,
        folds = folds,
        reps = reps,
        seed = seed,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- dmlirmClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

